#include <iostream>
#include <vector>

int main() {
    std::vector<int> numbers; // Vector to store integers

    std::cout << "Enter a list of integers (type 0 to stop): ";

    int num; // Variable to store user input

    while (std::cin >> num) { // Read user input
        if (num == 0) { // Exit loop if 0 is entered
            break;
        }

        numbers.push_back(num); // Add number to vector
    }

    if (num != 0) { // Check if user entered any number
        int product = 1; // Initialize product to 1

        for (const auto& num : numbers) { // Calculate product
            product *= num;
        }

        std::cout << "Product of entered integers: " << product << std::endl; // Display product
    } else {
        std::cerr << "No integers entered." << std::endl; // Display error message
    }

    return 0;
}

```

